from __future__ import absolute_import
import time
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from .panels.view import ViewPanel
from .common_page import CommonPage
from .modals import AbortSoftwareDownloadModal, RollbackSoftwareModal, WebElementManagerReloadModal


class Software(CommonPage):
    """
    The class corresponding to software page on selenium_coam web, all operations under software
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self):
        if not self._instance_dict:
            self._instance_dict = {"Software Update": SoftwareUpdatePage()}
        super(Software, self).__init__(self._instance_dict)


class SoftwareUpdatePage(object):
    MENU_ROUTE_LIST = ['Software', 'Software Management', 'Software Update']

    def __init__(self):
        self._view_panel = SoftwareUpdatePageViewPanel()

    def load_software_package_from_local_drive(self, file_path, timeout):
        return self._view_panel.load_software_package_from_local_drive(file_path, timeout)

    def load_software_package_from_remote_server(self, url, sw_file, timeout):
        return self._view_panel.load_software_package_from_remote_server(url, sw_file, timeout)

    def software_update(self, is_activate, timeout):
        self._view_panel.software_update(is_activate, timeout)

    def cancel_software_update(self):
        self._view_panel.cancel_software_update()

    def check_software_update_progress(self):
        return self._view_panel.check_software_update_progress()

    def check_current_software_version(self, key):
        version = self._view_panel.get_all_current_software_version()
        return version if key is None else version[key]

    def save_sw_update_report(self, download_timeout):
        return self._view_panel.save_sw_update_report(download_timeout)

    def software_rollback(self):
        self._view_panel.software_rollback()

    def backup_bts_site_configuration(self, download_timeout):
        return self._view_panel.backup_bts_site_configuration(download_timeout)


class SoftwareUpdatePageViewPanel(ViewPanel):
    _LOCAL_DRIVE_RADIO_BOX_XPATH = "//label[contains(text(), 'Local drive')]"
    _REMOTE_SERVER_RADIO_BOX_XPATH = "//label[contains(text(), 'Remote server')]"
    _LOCAL_LOAD_HIDDEN_BUTTON_SCRIPT = "open-software-local ui-file-input input"
    _LOCAL_LOAD_HIDDEN_BUTTON_XPATH = "//*[text()=' Browse...']/../../input[@type='file']"
    _LOAD_INFO_XPATH = "//div[@class='package-info']/div"
    _LOAD_INFO_SUCCESS_XPATH = "//div[@class='package-info']//*[contains(text(), 'Software file check completed')]"
    _ACTIVATE_CHECKBOX_SELECTED_XPATH = "//input[@id='activate-checkbox']"
    _ACTIVATE_CHECKBOX_XPATH = "//input[@id='activate-checkbox']/../label"
    _START_UPDATE_BUTTON_XPATH = "//ui-button[@a-text='Start']/button[contains(text(), 'Start')]"
    _UPDATE_PROGRESS_CONTEXT_XPATH = "//div[@class='software-progress-root']/div/span"
    _UPDATE_PROGRESS_BAR_XPATH = "//div[@class='progress-bar']/span"
    _CANCEL_UPDATE_BUTTON_XPATH = "//button[contains(text(), 'Cancel')]"
    _VERSION_KEYS_XPATH = "//table[@class='current-table']//th"
    _VERSION_VALUES_XPATH = "//table[@class='current-table']//td[1]"
    _ROLLBACK_BUTTON_XPATH = "//button[contains(text(), 'Rollback...')]"
    _SAVE_SW_UPDATE_REPORT_BUTTON_XPATH = "//button[contains(text(),'Save SW Update Report')]"
    _BACKUP_CONFIGURATION_BUTTON = "//button[contains(text(), ' Backup BTS Site Configuration')]"

    def load_software_package_from_local_drive(self, file_path, timeout):
        try:
            self.select_radiobox_by_xpath(self._LOCAL_DRIVE_RADIO_BOX_XPATH)
            self.load_file_from_hidden_button(self._LOCAL_LOAD_HIDDEN_BUTTON_SCRIPT,
                                              self._LOCAL_LOAD_HIDDEN_BUTTON_XPATH, file_path, timeout)
            self.wait_for_visibility_by_xpath(self._LOAD_INFO_SUCCESS_XPATH, timeout)
            return "software package load success"
        except TimeoutException:
            error_text = self.get_text_by_xpath(self._LOAD_INFO_XPATH)
            if error_text:
                return error_text
            raise

    def load_software_package_from_remote_server(self, url, sw_file, timeout):
        self.select_radiobox_by_xpath(self._REMOTE_SERVER_RADIO_BOX_XPATH)
        # TODO it will be finished when test environment has been ready

    def software_update(self, is_activate, timeout):
        self.select_checkbox_by_specified_status(is_activate, self._ACTIVATE_CHECKBOX_SELECTED_XPATH,
                                                 self._ACTIVATE_CHECKBOX_XPATH)
        self.click_enabled_element_after_visible((By.XPATH, self._START_UPDATE_BUTTON_XPATH))

        reload_modal = WebElementManagerReloadModal()
        reload_modal.wait_until_login_modal_appear(timeout)
        reload_modal.confirm(timeout=6)

    def cancel_software_update(self):
        self.click_enabled_element_after_visible((By.XPATH, self._CANCEL_UPDATE_BUTTON_XPATH))
        abort_software_download_modal = AbortSoftwareDownloadModal()
        abort_software_download_modal.wait_until_abort_software_download_modal_appear()
        abort_software_download_modal.abort()

    def check_software_update_progress(self):
        text = self.get_text_by_xpath(self._UPDATE_PROGRESS_CONTEXT_XPATH)
        percentage = self.get_text_by_xpath(self._UPDATE_PROGRESS_BAR_XPATH)
        return {'status': text, 'percentage': percentage}

    def get_all_current_software_version(self):
        return self.get_dict_from_elements_by_xpath(self._VERSION_KEYS_XPATH, self._VERSION_VALUES_XPATH, ':')

    def software_rollback(self):
        self.click_enabled_element_after_visible((By.XPATH, self._ROLLBACK_BUTTON_XPATH))
        rollback_software_modal = RollbackSoftwareModal()
        rollback_software_modal.wait_until_rollback_software_modal_appear()
        rollback_software_modal.rollback()

    def _download_files_by_xpath(self, xpath, download_timeout):
        start_time = time.time()
        self.click_enabled_element_after_visible((By.XPATH, xpath))
        return self.download_files(start_time, download_timeout)

    def save_sw_update_report(self, download_timeout):
        return self._download_files_by_xpath(self._SAVE_SW_UPDATE_REPORT_BUTTON_XPATH, download_timeout)

    def backup_bts_site_configuration(self, download_timeout):
        return self._download_files_by_xpath(self._BACKUP_CONFIGURATION_BUTTON, download_timeout)
